mapper.update:
UPDATE hyperlink_billing_reservation SET reservation_status=2, pending_operation=0,
  reserved_amount=quoted_amount, external_reservation_no=#{externalNo}, reserved_at=#{reservedAt},
  operation_idempotency_key=NULL, next_retry_at=NULL, failure_code=NULL, failure_reason=NULL,
  version=version+1, updated_at=#{reservedAt}
WHERE hyperlink_task_id=#{taskId} AND reservation_status IN (1,6) AND pending_operation=1
  AND operation_idempotency_key=#{operationKey}

UPDATE hyperlink_billing_reservation SET reservation_status=2, pending_operation=0,
  reserved_amount=#{reservedAmount}, operation_idempotency_key=NULL, next_retry_at=NULL,
  failure_code=NULL, failure_reason=NULL, version=version+1, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId} AND reservation_status IN (1,2,3,4,6)
  AND pending_operation=2 AND operation_idempotency_key=#{operationKey}

UPDATE hyperlink_billing_reservation SET reservation_status=6, failure_code=#{failureCode},
  failure_reason=#{failureReason}, next_retry_at=#{nextRetryAt}, version=version+1, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId} AND pending_operation<>0

UPDATE hyperlink_billing_reservation SET reservation_status=5, pending_operation=0,
  released_amount=#{releasedAmount}, released_at=#{now},
  operation_idempotency_key=NULL, next_retry_at=NULL,
  failure_code=NULL, failure_reason=NULL, version=version+1, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId} AND pending_operation=4
  AND operation_idempotency_key=#{operationKey}
